const removeUserFromSCIMGroups = `-- name: RemoveUserFromSCIMGroups :many
DELETE FROM scim_group_members WHERE user_id = $1 RETURNING group_id
`

func (q *Queries) RemoveUserFromSCIMGroups(ctx context.Context, userID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, removeUserFromSCIMGroups, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var group_id uuid.UUID
		if err := rows.Scan(&group_id); err != nil {
			return nil, err
		}
		items = append(items, group_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const revokeSCIMToken = `-- name: RevokeSCIMToken :one
UPDATE scim_tokens SET revoked_at = now() WHERE id = $1 AND revoked_at IS NULL RETURNING id, name, digest, created_by, created_at, last_used_at, revoked_at
`

func (q *Queries) RevokeSCIMToken(ctx context.Context, id uuid.UUID) (ScimToken, error) {
	row := q.db.QueryRow(ctx, revokeSCIMToken, id)
	var i ScimToken
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Digest,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.LastUsedAt,
		&i.RevokedAt,
	)
	return i, err
}

const sCIMGroupsOfUser = `-- name: SCIMGroupsOfUser :many
SELECT g.display_name, coalesce(g.external_id, '')::text AS external_id
FROM scim_group_members m JOIN scim_groups g ON g.id = m.group_id WHERE m.user_id = $1
`

type SCIMGroupsOfUserRow struct {
	DisplayName string
	ExternalID  string
}

// A user's groups for the SSO rules: each SCIM group's name and external ID.
func (q *Queries) SCIMGroupsOfUser(ctx context.Context, userID uuid.UUID) ([]SCIMGroupsOfUserRow, error) {
	rows, err := q.db.Query(ctx, sCIMGroupsOfUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SCIMGroupsOfUserRow{}
	for rows.Next() {
		var i SCIMGroupsOfUserRow
		if err := rows.Scan(&i.DisplayName, &i.ExternalID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sCIMSummary = `-- name: SCIMSummary :one
SELECT (SELECT count(*) FROM users WHERE scim_external_id IS NOT NULL)::bigint AS users,
       (SELECT count(*) FROM users WHERE scim_external_id IS NOT NULL AND oidc_subject LIKE 'scim-pending:%')::bigint AS pending,
       (SELECT count(*) FROM scim_groups)::bigint AS groups
`

type SCIMSummaryRow struct {
	Users   int64
	Pending int64
	Groups  int64
}

func (q *Queries) SCIMSummary(ctx context.Context) (SCIMSummaryRow, error) {
	row := q.db.QueryRow(ctx, sCIMSummary)
	var i SCIMSummaryRow
	err := row.Scan(&i.Users, &i.Pending, &i.Groups)
	return i, err
}

